import { KeyStore } from "./key-store_node.js";
import { KeyChain, KeyChainSerialized } from "./keychain_node.js";
/**
 * KeyChain adapter that copies from an external KeyChain.
 */
export class KeyChainExternal extends KeyChainSerialized {
    algoList;
    needJwk;
    insertKeyLoader;
    cached;
    constructor(algoList, needJwk = true) {
        super();
        this.algoList = algoList;
        this.needJwk = needJwk;
        this.insertKeyLoader = new KeyStore.Loader(needJwk, algoList);
    }
    async load() {
        return (this.cached ??= await this.copyTo(KeyChain.createTemp(this.algoList)));
    }
    async sListKeys(prefix) {
        const keyChain = await this.load();
        return keyChain.listKeys(prefix);
    }
    async sGetKeyPair(name) {
        const keyChain = await this.load();
        return keyChain.getKeyPair(name);
    }
    async sInsertKey(name, stored) {
        const keyPair = await this.insertKeyLoader.loadKey(name, stored);
        try {
            await this.eInsertKey(keyPair);
        }
        finally {
            delete this.cached;
        }
    }
    async sDeleteKey(name) {
        try {
            await this.eDeleteKey(name);
        }
        finally {
            delete this.cached;
        }
    }
    async sListCerts(prefix) {
        const keyChain = await this.load();
        return keyChain.listCerts(prefix);
    }
    async sGetCert(name) {
        const keyChain = await this.load();
        return keyChain.getCert(name);
    }
    async sInsertCert(cert) {
        try {
            await this.eInsertCert(cert);
        }
        finally {
            delete this.cached;
        }
    }
    async sDeleteCert(name) {
        try {
            await this.eDeleteCert(name);
        }
        finally {
            delete this.cached;
        }
    }
}
